<script setup lang="ts">
import { privateFileBlob, uploadPrivate } from '@/services/private-files'

import{onMounted,reactive,ref}from'vue';import{apiErrorMessage,http}from'@/services/http';import type{ApiResponse,MoralFile,Period}from'@/types/api';import{labelOf}from'@/utils/labels'
const periods=ref<Period[]>([]),items=ref<MoralFile[]>([]),file=ref<File|null>(null),form=reactive({periodId:'' as number|'',title:''}),error=ref(''),success=ref(''),busy=ref(false)
async function load(){try{const[p,f]=await Promise.all([http.get<ApiResponse<Period[]>>('/periods'),http.get<ApiResponse<MoralFile[]>>('/admin/moral-files',{params:{periodId:form.periodId||undefined}})]);periods.value=p.data.data;items.value=f.data.data;if(!form.periodId&&periods.value.length)form.periodId=periods.value[0].id}catch(e){error.value=apiErrorMessage(e)}}
async function upload(){if(!file.value)return;busy.value=true;const d=new FormData();d.append('periodId',String(form.periodId));d.append('title',form.title);d.append('file',file.value);try{await uploadPrivate('/admin/moral-files',d,{kind:'MORAL',periodId:form.periodId,title:form.title});success.value='文件已保存为草稿，学生暂不可见。';form.title='';file.value=null;await load()}catch(e){error.value=apiErrorMessage(e)}finally{busy.value=false}}
async function action(item:MoralFile,kind:'publish'|'withdraw'|'delete'){if(kind==='delete'&&!confirm('确认删除该文件记录？已发布文件须先撤回。'))return;busy.value=true;try{kind==='delete'?await http.delete(`/admin/moral-files/${item.id}`):await http.post(`/admin/moral-files/${item.id}/${kind}`);success.value=kind==='publish'?'文件已发布，学生现在可以下载。':kind==='withdraw'?'文件已撤回，学生端立即不可见。':'文件已软删除并保留审计记录。';await load()}catch(e){error.value=apiErrorMessage(e)}finally{busy.value=false}}
async function download(item:MoralFile){try{const blob=await privateFileBlob(item.downloadUrl);const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=item.originalFilename;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){error.value=apiErrorMessage(e)}}onMounted(load)
</script>
<template><div v-if="error" class="notice danger">{{error}}</div><div v-if="success" class="notice success">{{success}}</div><article class="card"><header><div><h2>上传德育素质分文件</h2><p>平台只负责发布文件，不计算德育素质分。</p></div></header><form class="card-body form-grid" @submit.prevent="upload"><label>活动期次<select v-model="form.periodId" required @change="load"><option disabled value="">请选择</option><option v-for="p in periods" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>文件标题<input v-model="form.title" maxlength="200" required /></label><label class="full-row">选择文件<input type="file" accept=".csv,.xls,.xlsx,.pdf" required @change="file=($event.target as HTMLInputElement).files?.[0]||null" /></label><div class="notice full-row">支持 CSV、XLS、XLSX、PDF，单个文件不超过20MB；上传后默认为草稿。</div><div class="form-actions full-row"><button class="button primary" :disabled="busy||!file">上传为草稿</button></div></form></article><article class="card"><header><div><h2>文件发布管理</h2><p>撤回后学生端立即不可见；删除采用留痕的软删除。</p></div></header><div class="table-wrap"><table><thead><tr><th>标题</th><th>期次</th><th>状态</th><th>文件</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{item.title}}<small>{{new Date(item.createdAt).toLocaleString('zh-CN')}}</small></td><td>{{item.periodName}}</td><td><span class="status-badge" :class="item.status==='PUBLISHED'?'approved':item.status==='DRAFT'?'pending':'rejected'">{{labelOf(item.status)}}</span></td><td>{{item.originalFilename}}<small>{{(item.fileSize/1024).toFixed(1)}} KB</small></td><td><div class="table-actions"><button class="button ghost small" @click="download(item)">下载</button><button v-if="item.status!=='PUBLISHED'" class="button primary small" :disabled="busy" @click="action(item,'publish')">发布</button><button v-if="item.status==='PUBLISHED'" class="button secondary small" :disabled="busy" @click="action(item,'withdraw')">撤回</button><button v-if="item.status!=='PUBLISHED'" class="button danger small" :disabled="busy" @click="action(item,'delete')">删除</button></div></td></tr></tbody></table></div></article></template>
